'use strict';
const PICKER_ARCHIVE_LIMIT=6,PICKER_ITEM_LIMIT=8,COLLECTION_LIMIT=12;
let sidebarArchiveQuery='',sidebarArchiveExpanded=false;
const searchable=s=>String(s||'').toLocaleLowerCase();
function capped(items,expanded,limit=PICKER_ITEM_LIMIT){return expanded?items:items.slice(0,limit)}
function smartPicker({items,selected,kind,multiple,onSelect,ariaLabel}){
 const root=document.createElement('div');root.className='smartPicker';let query='',archive='',allArchives=false,allItems=false,selectedOnly=false;const pool=items.map(item=>({...item,haystack:searchable([item.name,item.archiveName,item.detail].join(' '))}));
 root.innerHTML='<div class="pickerTop"><input class="pickerSearch" type="search"><button type="button" class="pickerSelected"></button></div><div class="pickerArchives"></div><div class="pickerResults"></div><div class="pickerBottom"><span class="pickerCount" aria-live="polite"></span><button type="button" class="pickerMore" hidden></button></div>';
 const search=root.querySelector('.pickerSearch'),selectedButton=root.querySelector('.pickerSelected'),archives=root.querySelector('.pickerArchives'),results=root.querySelector('.pickerResults'),more=root.querySelector('.pickerMore'),count=root.querySelector('.pickerCount');search.placeholder=ariaLabel||'搜索名称…';search.setAttribute('aria-label',ariaLabel||'搜索名称');
 function draw(){const chosen=selected();selectedButton.textContent=multiple?'已选 '+chosen.size:'当前：'+(pool.find(i=>chosen.has(i.id))?.name||'未选择');selectedButton.setAttribute('aria-pressed',String(selectedOnly));selectedButton.title=multiple?'仅看已选，再点一次显示全部':'查看当前选项';const groups=[...new Map(pool.filter(i=>i.archiveId).map(i=>[i.archiveId,i.archiveName])).entries()];archives.hidden=!groups.length;archives.innerHTML=groups.length?`<button type="button" data-picker-archive="" class="${!archive?'active':''}">全部档案</button>`+capped(groups,allArchives,PICKER_ARCHIVE_LIMIT).map(([id,name])=>`<button type="button" data-picker-archive="${esc(id)}" class="${archive===id?'active':''}">${esc(name)}</button>`).join('')+(groups.length>PICKER_ARCHIVE_LIMIT?`<button type="button" data-more-archives="true">${allArchives?'收起档案':'展开全部档案（'+groups.length+'）'}</button>`:''):'';const found=pool.filter(i=>(!archive||i.archiveId===archive)&&(!query||i.haystack.includes(query))&&(!selectedOnly||chosen.has(i.id)));const visible=capped(found,allItems);results.replaceChildren();if(!visible.length){const empty=document.createElement('p');empty.className='hint pickerEmpty';empty.textContent='没有匹配项，可清空搜索或切换到全部档案。';results.append(empty)}for(const item of visible){if(item.node){item.node.hidden=false;results.append(item.node)}else{const b=document.createElement('button');b.type='button';b.className='pickerOption';b.dataset.pickerOption=item.id;b.setAttribute('aria-pressed',String(chosen.has(item.id)));b.innerHTML=`<span>${esc(item.name)}</span>${item.detail?'<small>'+esc(item.detail)+'</small>':''}`;results.append(b)}}// Checked inputs remain in the form even when their labels are filtered out.
 for(const item of pool){if(item.node&&!visible.includes(item)){item.node.hidden=true;results.append(item.node)}}count.textContent=`显示 ${visible.length} / ${found.length} 项${multiple?' · 已选 '+chosen.size:''}`;more.hidden=found.length<=PICKER_ITEM_LIMIT;more.textContent=allItems?'收起列表':'展开全部（'+found.length+'）';}
 search.oninput=()=>{query=searchable(search.value.trim());allItems=false;draw()};selectedButton.onclick=()=>{selectedOnly=!selectedOnly;archive='';allItems=false;draw()};more.onclick=()=>{allItems=!allItems;draw()};archives.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.moreArchives){allArchives=!allArchives;draw()}else if(b.dataset.pickerArchive!==undefined){archive=b.dataset.pickerArchive;selectedOnly=false;allItems=false;draw()}};results.onclick=e=>{const b=e.target.closest('[data-picker-option]');if(b){onSelect(b.dataset.pickerOption);draw()}};results.onchange=e=>{if(e.target.matches('input[type=checkbox]'))draw()};root.refresh=draw;draw();return root;
}
function upgradeChecks(container){if(container.dataset.smartChecks)return;const labels=[...container.querySelectorAll('label')].filter(l=>l.querySelector('input[type=checkbox]'));if(!labels.length)return;container.dataset.smartChecks='true';const kind=labels[0].querySelector('input').name==='games'?'games':'characters';const items=labels.map(label=>{const input=label.querySelector('input'),x=kind==='games'?game(input.value):character(input.value);return{id:input.value,name:x?.name||label.textContent.trim(),archiveId:kind==='characters'?x?.gameId:'',archiveName:kind==='characters'?game(x?.gameId)?.name:'',node:label}});const inputs=labels.map(l=>l.querySelector('input'));const picker=smartPicker({items,kind,multiple:true,selected:()=>new Set(inputs.filter(i=>i.checked).map(i=>i.value)),onSelect:()=>{},ariaLabel:kind==='characters'?'搜索角色或档案…':'搜索档案…'});container.classList.add('smartChecksHost');container.replaceChildren(picker)}
function selectKind(select){if(['relationA','relationB'].includes(select.id))return'characters';if(['profileGame','mapArchiveId','mapArchive'].includes(select.id))return'games';if(['assetAlbum','albumSelect'].includes(select.id)||select.classList.contains('pickAlbum'))return'albums';if(select.id==='mapSelect')return'maps';if(select.id==='mapGroup')return'groups';return null}
function upgradeSelect(select){if(select.dataset.smartSelect)return;const kind=selectKind(select);if(!kind)return;const options=[...select.options];if(options.length<=6&&!['characters','games'].includes(kind))return;select.dataset.smartSelect='true';const oldLabel=select.closest('label'),label=oldLabel?.childNodes[0]?.textContent?.trim()||select.getAttribute('aria-label')||'选择项目';const items=options.map(o=>{const x=kind==='characters'?character(o.value):kind==='maps'?(data.maps||[]).find(m=>m.id===o.value):null;return{id:o.value,name:kind==='characters'&&x?x.name:o.textContent,archiveId:x?.gameId||x?.archiveId||'',archiveName:game(x?.gameId||x?.archiveId)?.name||'',detail:kind==='characters'?game(x?.gameId)?.name||'':''}});const disclosure=document.createElement('details');disclosure.className='selectorDisclosure';const summary=document.createElement('summary');const updateSummary=()=>{summary.textContent=select.options[select.selectedIndex]?.textContent||'请选择'};updateSummary();const picker=smartPicker({items,kind,multiple:false,selected:()=>new Set([select.value]),onSelect:id=>{select.value=id;select.dispatchEvent(new Event('change',{bubbles:true}));disclosure.open=false},ariaLabel:'搜索'+(kind==='characters'?'角色或档案':kind==='games'?'档案':kind==='albums'?'相册':kind==='groups'?'分组':'关系图')+'…'});picker.classList.add('singlePicker');picker.setAttribute('aria-label',label);select.hidden=true;select.classList.add('smartNative');disclosure.append(summary,picker);if(oldLabel)oldLabel.after(disclosure);else select.after(disclosure);select.addEventListener('change',()=>{updateSummary();picker.refresh()})}
function enhanceDialog(root){root.querySelectorAll('.checks').forEach(upgradeChecks);root.querySelectorAll('select').forEach(upgradeSelect)}
const catalogueModal=modal;modal=function(html){catalogueModal(html);enhanceDialog($('dialog'))};
const catalogueFloating=floating;floating=function(html){const d=catalogueFloating(html);enhanceDialog(d);return d};
function limitButtons(container,{limit=PICKER_ITEM_LIMIT,label='项目',search=true}={}){if(!container||(container.dataset.catalogued&&container.querySelector(':scope > .collectionTools')))return;const buttons=[...container.children].filter(n=>n.tagName==='BUTTON');if(buttons.length<=limit&&!search)return;if(!buttons.length)return;container.dataset.catalogued='true';container.classList.add('cataloguedList');const controls=document.createElement('div');controls.className='collectionTools';let query='',expanded=false;const input=document.createElement('input');input.type='search';input.placeholder='搜索'+label+'…';input.setAttribute('aria-label','搜索'+label);if(search&&buttons.length>5)controls.append(input);const toggle=document.createElement('button');toggle.type='button';toggle.className='collectionToggle';controls.append(toggle);container.prepend(controls);function draw(){const found=buttons.filter(b=>searchable(b.textContent).includes(query));buttons.forEach(b=>b.hidden=true);capped(found,expanded,limit).forEach(b=>b.hidden=false);toggle.hidden=found.length<=limit;toggle.textContent=expanded?'收起列表':'展开全部（'+found.length+'）';controls.hidden=!controls.children.length||(input.parentElement!==controls&&toggle.hidden)}input.oninput=()=>{query=searchable(input.value.trim());expanded=false;draw()};toggle.onclick=()=>{expanded=!expanded;draw()};draw()}
function enhanceSidebar(){const games=$('games');if(!games)return;let tools=$('archiveSearchTools');if(!tools){tools=document.createElement('div');tools.id='archiveSearchTools';tools.className='archiveSearchTools';tools.innerHTML='<input id="archiveSearch" type="search" placeholder="搜索档案…" aria-label="搜索我的档案"><div class="archiveSearchFoot"><span id="archiveSearchCount"></span><button type="button" id="archiveSearchMore" hidden></button></div>';games.before(tools);$('archiveSearch').value=sidebarArchiveQuery;$('archiveSearch').oninput=()=>{sidebarArchiveQuery=$('archiveSearch').value;sidebarArchiveExpanded=false;drawSidebar()};$('archiveSearchMore').onclick=()=>{sidebarArchiveExpanded=!sidebarArchiveExpanded;drawSidebar()}}drawSidebar()}
function drawSidebar(){const buttons=[...$('games').querySelectorAll('[data-view=game]')],q=searchable(sidebarArchiveQuery.trim()),found=buttons.filter(b=>searchable(b.textContent).includes(q));buttons.forEach(b=>b.hidden=true);capped(found,sidebarArchiveExpanded,PICKER_ARCHIVE_LIMIT).forEach(b=>b.hidden=false);$('archiveSearchCount').textContent=`${found.length} 个档案`;$('archiveSearchMore').hidden=found.length<=PICKER_ARCHIVE_LIMIT;$('archiveSearchMore').textContent=sidebarArchiveExpanded?'收起':'展开全部';let empty=$('archiveSearchEmpty');if(!empty){empty=document.createElement('p');empty.id='archiveSearchEmpty';empty.className='hint';$('games').append(empty)}empty.hidden=found.length!==0;empty.textContent=q?'没有匹配的档案':'还没有档案'}
function enhanceProfileLists(){document.querySelectorAll('#profile .chips').forEach(n=>limitButtons(n,{label:view.type==='game'?'角色':'关系'}))}
function limitCards(container,selector,label,limit=COLLECTION_LIMIT){if(!container)return;container.querySelector(':scope > .cardListToggle')?.remove();const cards=[...container.querySelectorAll(selector)];cards.forEach(n=>n.hidden=false);if(cards.length<=limit)return;let expanded=false;const b=document.createElement('button');b.type='button';b.className='cardListToggle';function draw(){cards.forEach((n,i)=>n.hidden=!expanded&&i>=limit);b.textContent=expanded?'收起'+label:'展开全部'+label+'（'+cards.length+'）'}b.onclick=()=>{expanded=!expanded;draw()};container.append(b);draw()}
function enhanceFeedCollections(){document.querySelectorAll('.journalPost>.chips').forEach(n=>limitButtons(n,{limit:8,label:'关联',search:false}));if(view.type==='relations')limitCards($('feed'),':scope > article.post','关系档案',8);const cards=$('mapCards');if(cards){limitButtons(cards,{limit:8,label:'关系图',search:false});}const albums=document.querySelector('.albumIndex');if(albums)limitButtons(albums,{limit:6,label:'相册'});document.querySelectorAll('.mapExplorer select,#albumSelect,#mapSelect').forEach(upgradeSelect);limitCards($('assetList'),':scope > .assetCard','图片');document.querySelectorAll('.pickGrid').forEach(n=>limitCards(n,':scope > button[data-pick]','图片'))}
const catalogueProfile=renderProfile;renderProfile=function(){catalogueProfile();enhanceProfileLists()};
const catalogueFilters=renderFilters;renderFilters=function(){catalogueFilters();limitButtons($('filters'),{limit:8,label:'标签'})};
const catalogueFeed=renderFeed;renderFeed=function(){catalogueFeed();enhanceFeedCollections()};
const catalogueGallery=renderGallery;renderGallery=function(){catalogueGallery();enhanceFeedCollections()};
const catalogueAssets=drawAssets;drawAssets=function(){catalogueAssets();limitCards($('assetList'),':scope > .assetCard','图片')};
const catalogueRender=render;render=function(){catalogueRender();if(ready)enhanceSidebar()};
document.addEventListener('input',e=>{if(e.target.id==='mapQuery'||e.target.classList.contains('pickQuery'))queueMicrotask(enhanceFeedCollections)});
document.addEventListener('change',e=>{if(['mapGroup','mapArchive'].includes(e.target.id)||e.target.classList.contains('pickAlbum'))queueMicrotask(enhanceFeedCollections)});

const cataloguePickAsset=pickAsset;pickAsset=function(done){cataloguePickAsset(done);document.querySelectorAll('dialog .pickGrid').forEach(n=>limitCards(n,':scope > button[data-pick]','图片'))};
